/* Palette: #1a1a2e (bg), #16213e (card), #0f3460 (accent), #e94560 (highlight), #f5f5f5 (text) */

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  background: #1a1a2e;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  color: #f5f5f5;
}

.card {
  background: #16213e;
  border-radius: 1.5rem;
  padding: 2rem 1.5rem;
  width: 100%;
  max-width: 400px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
  border: 2px solid #0f3460;
}

h1 {
  font-size: 1.5rem;
  text-align: center;
  margin-bottom: 1.5rem;
  letter-spacing: 0.05em;
  color: #e94560;
  text-transform: uppercase;
}

.display {
  background: #0f3460;
  border-radius: 0.75rem;
  padding: 1rem;
  text-align: center;
  font-size: 1.25rem;
  min-height: 4rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.25rem;
  margin-bottom: 1.5rem;
  border: 2px solid #1a1a2e;
  word-break: break-word;
}

#status {
  font-weight: 600;
}

#countdown {
  font-size: 0.9rem;
  color: #e94560;
}

.keypad {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.75rem;
}

.key {
  background: #0f3460;
  color: #f5f5f5;
  border: 2px solid #1a1a2e;
  border-radius: 0.75rem;
  padding: 1rem 0;
  font-size: 1.25rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
  min-height: 3.5rem;
  user-select: none;
}

.key:hover:not(:disabled) {
  background: #1a4a7a;
  border-color: #e94560;
}

.key:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 2px;
}

.key:active:not(:disabled) {
  background: #e94560;
  transform: scale(0.96);
}

.key:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.key.action {
  background: #e94560;
  color: #fff;
  font-size: 1rem;
}

.key.action:hover:not(:disabled) {
  background: #ff5a75;
}

.key.action:active:not(:disabled) {
  background: #c0304a;
}

/* Responsive adjustments */
@media (max-width: 360px) {
  .card {
    padding: 1.25rem 0.75rem;
  }
  .keypad {
    gap: 0.5rem;
  }
  .key {
    padding: 0.75rem 0;
    font-size: 1.1rem;
    min-height: 3rem;
  }
  h1 {
    font-size: 1.25rem;
  }
  .display {
    font-size: 1.1rem;
    padding: 0.75rem;
  }
}

(function () {
  'use strict';

  const CORRECT_CODE = '4271';
  const MAX_ATTEMPTS = 3;
  const LOCKOUT_SECONDS = 10;

  let entered = '';
  let wrongAttempts = 0;
  let locked = false;
  let lockoutTimer = null;
  let countdownInterval = null;

  const displayEl = document.getElementById('display');
  const statusEl = document.getElementById('status');
  const countdownEl = document.getElementById('countdown');
  const digitButtons = document.querySelectorAll('[data-digit]');
  const clearBtn = document.getElementById('clearBtn');
  const enterBtn = document.getElementById('enterBtn');
  const allButtons = document.querySelectorAll('.key');

  function updateDisplay(text) {
    statusEl.textContent = text;
  }

  function clearCountdown() {
    if (countdownInterval) {
      clearInterval(countdownInterval);
      countdownInterval = null;
    }
    countdownEl.hidden = true;
    countdownEl.textContent = '';
  }

  function setButtonsDisabled(disabled) {
    allButtons.forEach(function (btn) {
      btn.disabled = disabled;
    });
  }

  function lockKeypad() {
    locked = true;
    setButtonsDisabled(true);
    let remaining = LOCKOUT_SECONDS;
    updateDisplay('Locked out');
    countdownEl.hidden = false;
    countdownEl.textContent = 'Try again in ' + remaining + 's';

    countdownInterval = setInterval(function () {
      remaining -= 1;
      if (remaining > 0) {
        countdownEl.textContent = 'Try again in ' + remaining + 's';
      } else {
        clearInterval(countdownInterval);
        countdownInterval = null;
        countdownEl.hidden = true;
        countdownEl.textContent = '';
        locked = false;
        wrongAttempts = 0;
        setButtonsDisabled(false);
        updateDisplay('Enter code');
      }
    }, 1000);
  }

  function handleDigit(digit) {
    if (locked) return;
    if (entered.length >= 4) return;
    entered += digit;
    updateDisplay(entered);
  }

  function handleClear() {
    if (locked) return;
    entered = '';
    updateDisplay('Enter code');
  }

  function handleEnter() {
    if (locked) return;
    if (entered.length !== 4) {
      updateDisplay('Enter 4 digits');
      return;
    }

    if (entered === CORRECT_CODE) {
      updateDisplay('Unlocked');
      wrongAttempts = 0;
      entered = '';
      setButtonsDisabled(true);
      setTimeout(function () {
        if (!locked) {
          setButtonsDisabled(false);
          updateDisplay('Enter code');
        }
      }, 2000);
    } else {
      wrongAttempts += 1;
      entered = '';
      if (wrongAttempts >= MAX_ATTEMPTS) {
        lockKeypad();
      } else {
        updateDisplay('Wrong code');
        setTimeout(function () {
          if (!locked) updateDisplay('Enter code');
        }, 1500);
      }
    }
  }

  digitButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      handleDigit(btn.getAttribute('data-digit'));
    });
  });

  clearBtn.addEventListener('click', handleClear);
  enterBtn.addEventListener('click', handleEnter);

  document.addEventListener('keydown', function (e) {
    if (locked) return;
    if (e.key >= '0' && e.key <= '9') {
      handleDigit(e.key);
      e.preventDefault();
    } else if (e.key === 'Enter') {
      handleEnter();
      e.preventDefault();
    } else if (e.key === 'Escape' || e.key === 'Delete') {
      handleClear();
      e.preventDefault();
    }
  });
})();
